package com.ruoyi.system.messaging;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ruoyi.common.core.messaging.QueueKind;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;import java.util.*;
@Service public class QueueControlStore {
 @Resource JdbcTemplate db;private static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 public static String s(Map<String,?> r,String k){return r.get(k)==null?"":r.get(k).toString();}
 public static long n(Map<String,?> r,String k){try{return Long.parseLong(s(r,k));}catch(Exception e){return 0;}}
 static void require(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 static String json(Object value){try{return JSON.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("配置内容无法保存");}}
 @SuppressWarnings("unchecked") static Map<String,Object> decode(Object value){try{return value==null?new LinkedHashMap<>():JSON.readValue(value.toString(),Map.class);}catch(Exception e){return new LinkedHashMap<>();}}
 <T>T tx(java.util.function.Supplier<T> work){return new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource())).execute(t->work.get());}
 Map<String,Object> policy(QueueKind k){Map<String,Object> r=db.queryForMap("SELECT * FROM sys_mq_queue_policy WHERE business_type=?",k.name());r.putAll(k.metadata());return r;}
 public List<Map<String,Object>> snapshot(String service,String instance){instance(service,instance);List<Map<String,Object>> result=new ArrayList<>();for(QueueKind k:QueueKind.service(service)){db.update("INSERT IGNORE INTO sys_mq_instance(business_type,instance_id,service_code) VALUES (?,?,?)",k.name(),instance,service);result.add(policy(k));}return result;}
 void instance(String service,String instance){QueueKind.service(service);require(instance!=null&&instance.matches("[A-Za-z0-9_.:-]{1,96}"),"消费实例标识无效");}
 @SuppressWarnings("unchecked") public void heartbeat(Map<String,Object> body){String service=s(body,"service"),instance=s(body,"instance");instance(service,instance);require(body.get("queues") instanceof List&&((List<?>)body.get("queues")).size()<=QueueKind.service(service).size(),"实例回报范围无效");for(Map<String,Object> r:(List<Map<String,Object>>)body.get("queues")){QueueKind k=QueueKind.of(s(r,"business_type"));require(k.service.equals(service),"不能回报其他服务的队列");require(n(r,"actual_consumers")>=0&&n(r,"actual_consumers")<=16&&n(r,"active_work")>=0&&n(r,"active_work")<=16&&n(r,"applied_version")>=0,"消费实例数据无效");require(Arrays.asList("STARTING","APPLYING","RUNNING","CONNECTING","DRAINING","PAUSED","ERROR","STOPPED").contains(s(r,"state")),"消费实例状态无效");if("STOPPED".equals(s(r,"state")))require(n(r,"active_work")==0&&n(r,"actual_consumers")==0,"退出实例不能保留在途任务或消费者");String error=s(r,"last_error");require(error.length()<=255,"错误说明过长");String stats=json(r.getOrDefault("stats",Collections.emptyMap()));require(stats.length()<=4096,"监控数据超出范围");db.update("INSERT INTO sys_mq_instance(business_type,instance_id,service_code,applied_version,state,actual_consumers,active_work,last_error,stats_json,last_seen) VALUES (?,?,?,?,?,?,?,?,?,NOW(3)) ON DUPLICATE KEY UPDATE applied_version=VALUES(applied_version),state=VALUES(state),actual_consumers=VALUES(actual_consumers),active_work=VALUES(active_work),last_error=VALUES(last_error),stats_json=VALUES(stats_json),last_seen=NOW(3)",k.name(),instance,service,n(r,"applied_version"),s(r,"state"),n(r,"actual_consumers"),n(r,"active_work"),error,stats);}}
 public Map<String,Object> save(String type,Map<String,Object> input,String actor){QueueKind k=QueueKind.of(type);String mode=s(input,"desired_mode"),reason=s(input,"reason").trim();require(Arrays.asList("RUNNING","PAUSED").contains(mode)&&!reason.isEmpty()&&reason.length()<=255,"请选择运行状态并填写255字以内的修改依据");String[] fields={"concurrency","prefetch","retry_limit","retry_base_sec","retry_max_sec","compensate_after_sec","compensate_batch","app_rate","shop_rate","alarm_backlog","alarm_due_sec","alarm_failure_pct"};long[] min={1,1,1,5,5,30,1,1,1,1,30,1},max={8,50,20,300,3600,3600,20,20,20,100000,86400,100};for(int i=0;i<fields.length;i++)require(n(input,fields[i])>=min[i]&&n(input,fields[i])<=max[i],"队列配置超出范围："+fields[i]);require(n(input,"retry_max_sec")>=n(input,"retry_base_sec"),"最大重试间隔不能小于初始间隔");return tx(()->{List<Map<String,Object>> all=db.queryForList("SELECT * FROM sys_mq_queue_policy ORDER BY business_type FOR UPDATE");Map<String,Object> old=all.stream().filter(r->type.equals(s(r,"business_type"))).findFirst().orElseThrow(()->new IllegalArgumentException("队列未初始化"));require(n(old,"revision")==n(input,"revision"),"队列配置已变化，请刷新后重试");long total=n(input,"concurrency");for(Map<String,Object> r:all)if(!type.equals(s(r,"business_type"))&&QueueKind.of(s(r,"business_type")).service.equals(k.service))total+=n(r,"concurrency");require(total<=QueueKind.maxConcurrency(k.service),"当前服务每实例的消费并发总数不能超过"+QueueKind.maxConcurrency(k.service));List<Object> args=new ArrayList<>();StringBuilder set=new StringBuilder("desired_mode=?");args.add(mode);for(String field:fields){set.append(",").append(field).append("=?");args.add(n(input,field));}args.add(actor);args.add(type);db.update("UPDATE sys_mq_queue_policy SET "+set+",revision=revision+1,updated_by=? WHERE business_type=?",args.toArray());Map<String,Object> next=policy(k);db.update("INSERT INTO sys_mq_operation(business_type,revision,actor,reason,before_json,after_json) VALUES (?,?,?,?,?,?)",type,n(next,"revision"),actor,reason,json(old),json(next));return next;});}
 /** Shared per-app and per-shop admission across service instances; no waiting thread. */
 public boolean rate(String service,String instance,String type,List<String> keys){instance(service,instance);QueueKind k=QueueKind.of(type);require(k.service.equals(service)&&k.platformRateLimited()&&keys!=null&&keys.size()==2&&!keys.get(0).equals(keys.get(1)),"平台限流范围无效");for(String key:keys)require(key.matches("[a-f0-9]{64}"),"限流标识无效");return tx(()->{Map<String,Object> p=policy(k);if(!"RUNNING".equals(s(p,"desired_mode")))return false;Map<String,Object> shared=db.queryForMap("SELECT MIN(app_rate) app_rate,MIN(shop_rate) shop_rate FROM sys_mq_queue_policy WHERE business_type IN ('PRODUCT_PULL','EXCHANGE_PULL','EXCHANGE_FLOW','REFUND_FLOW','REFUND_PLATFORM','REFUND_API_PULL','REFUND_API_DETAIL')");List<String> sorted=new ArrayList<>(keys);Collections.sort(sorted);for(String key:sorted){db.update("INSERT IGNORE INTO sys_mq_rate_slot(slot_key,next_at) VALUES (?,NOW(3))",key);Map<String,Object> slot=db.queryForMap("SELECT next_at>NOW(3) blocked FROM sys_mq_rate_slot WHERE slot_key=? FOR UPDATE",key);if(n(slot,"blocked")==1)return false;}for(int i=0;i<keys.size();i++)db.update("UPDATE sys_mq_rate_slot SET next_at=DATE_ADD(NOW(3),INTERVAL ? MICROSECOND) WHERE slot_key=?",1000000/Math.max(1,n(shared,i==0?"app_rate":"shop_rate")),keys.get(i));return true;});}
 public List<Map<String,Object>> overview(){List<Map<String,Object>> rows=new ArrayList<>();for(QueueKind k:QueueKind.values())rows.add(detail(k.name(),false));return rows;}
 public Map<String,Object> detail(String type,boolean history){QueueKind k=QueueKind.of(type);Map<String,Object> r=policy(k);List<Map<String,Object>> instances=db.queryForList("SELECT *,TIMESTAMPDIFF(SECOND,last_seen,NOW(3)) heartbeat_age FROM sys_mq_instance WHERE business_type=? ORDER BY last_seen DESC LIMIT 100",type);boolean applied=true;int participants=0;long consumers=0,active=0;Map<String,Object> business=new LinkedHashMap<>();for(Map<String,Object> node:instances){boolean retired="STOPPED".equals(s(node,"state"))||n(node,"heartbeat_age")>240;boolean fresh=!retired&&n(node,"heartbeat_age")<=30;node.put("retired",retired);node.put("online",fresh);if(!retired)participants++;if(!retired&&(!fresh||n(node,"applied_version")!=n(r,"revision")||!s(node,"state").equals(s(r,"desired_mode"))))applied=false;if(!retired&&"PAUSED".equals(s(r,"desired_mode"))&&(n(node,"active_work")>0||n(node,"actual_consumers")>0))applied=false;if(fresh){consumers+=n(node,"actual_consumers");active+=n(node,"active_work");}Map<String,Object> stats=decode(node.remove("stats_json"));node.put("stats",stats);if(fresh&&n(stats,"sampled_ms")>n(business,"sampled_ms"))business=stats;dates(node);}Map<String,Object> aggregate=db.queryForMap("SELECT COUNT(*) participants,COALESCE(SUM(applied_version<>? OR state<>? OR last_seen<DATE_SUB(NOW(3),INTERVAL 30 SECOND) OR (?='PAUSED' AND (active_work>0 OR actual_consumers>0))),0) unapplied,COALESCE(SUM(IF(last_seen>=DATE_SUB(NOW(3),INTERVAL 30 SECOND),actual_consumers,0)),0) consumers,COALESCE(SUM(IF(last_seen>=DATE_SUB(NOW(3),INTERVAL 30 SECOND),active_work,0)),0) active FROM sys_mq_instance WHERE business_type=? AND state<>'STOPPED' AND last_seen>=DATE_SUB(NOW(3),INTERVAL 240 SECOND)",n(r,"revision"),s(r,"desired_mode"),s(r,"desired_mode"),type);participants=(int)n(aggregate,"participants");applied=n(aggregate,"unapplied")==0;r.put("instances",instances);r.put("instance_count",participants);r.put("actual_consumers",n(aggregate,"consumers"));r.put("active_work",n(aggregate,"active"));r.put("business",business);r.put("effective_state",participants==0?"NO_INSTANCES":applied?s(r,"desired_mode"):s(r,"desired_mode").equals("PAUSED")?"PAUSING":"APPLYING");List<Map<String,Object>> samples=db.queryForList("SELECT *,TIMESTAMPDIFF(SECOND,sampled_at,NOW(3)) sample_age FROM sys_mq_queue_snapshot WHERE business_type=?",type);Map<String,Object> sample=samples.isEmpty()?new LinkedHashMap<>():samples.get(0);sample.put("data",decode(sample.remove("payload_json")));sample.put("fresh",!samples.isEmpty()&&n(sample,"sample_age")<=45&&s(sample,"last_error").isEmpty());r.put("broker",dates(sample));r.put("quarantine_pending",db.queryForObject("SELECT COUNT(*) FROM sys_mq_dead_letter WHERE business_type=? AND ((verified=1 AND business_state<>'SUCCESS') OR (verified=0 AND reviewed_at IS NULL))",Long.class,type));r.put("alerts",db.queryForList("SELECT * FROM sys_mq_alert WHERE business_type IN (?, '*') AND state IN ('PENDING','FIRING') ORDER BY first_seen",type));if(history){r.put("operations",db.queryForList("SELECT revision,actor,reason,create_time FROM sys_mq_operation WHERE business_type=? ORDER BY id DESC LIMIT 50",type));r.put("alert_history",db.queryForList("SELECT rule_code,state,message,create_time FROM sys_mq_alert_event WHERE business_type IN (?, '*') ORDER BY id DESC LIMIT 100",type));}return dates(r);}
 static Map<String,Object> dates(Map<String,Object> r){r.replaceAll((k,v)->v instanceof java.sql.Timestamp?((java.sql.Timestamp)v).toLocalDateTime().toString().replace('T',' '):v instanceof java.time.temporal.TemporalAccessor?v.toString().replace('T',' '):v);return r;}
}
